/**
 * Message an Agent Node - Version 1
 * Send a message to a n8n agent
 */


export interface MessageAnAgentV1Params {
/**
 * The agent to send the message to
 * @searchListMethod listAgents
 * @default {"mode":"list","value":""}
 */
    agentId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The message to send to the agent
 */
    message: string | Expression<string>;
/**
 * Whether to constrain the agent response to a JSON Schema you provide. The conforming object is returned on the "structuredOutput" field.
 * @default false
 */
    useStructuredOutput?: boolean | Expression<boolean>;
/**
 * The JSON Schema that the agent response must conform to
 * @hint Use &lt;a target="_blank" href="https://json-schema.org/"&gt;JSON Schema&lt;/a&gt; format
 * @displayOptions.show { useStructuredOutput: [true] }
 */
    outputSchema?: IDataObject | string | Expression<string>;
  advanced?: {
    /** Whether to stream the agent's response as it generates text
     * @default true
     */
    enableStreaming?: boolean | Expression<boolean>;
    /** Whether to call the agent once per input item or a single time for all items
     * @displayOptions.hide { /agentSource: ["inline"] }
     * @default allItems
     */
    invokeMode?: 'allItems' | 'perItem';
    /** Reuse an agent session to keep memory across runs. Leave empty to start a fresh session per execution.
     */
    sessionId?: string | Expression<string>;
    /** Whether to give the agent a tool to read other workflow nodes' execution data, beyond its own input
     * @displayOptions.hide { /agentSource: ["inline"] }
     * @default false
     */
    allowOtherNodesData?: boolean | Expression<boolean>;
  };
}

export type MessageAnAgentV1Output = {
  response: string;
  structuredOutput: unknown;
  usage: {
    promptTokens?: number;
    completionTokens?: number;
    totalTokens?: number;
  } | null;
  toolCalls: Array<{
    toolName?: string;
    input?: unknown;
    result?: unknown;
  }>;
  finishReason: string;
  session: {
    agentId?: string;
    projectId?: string;
    sessionId?: string;
    threadId?: string;
  } | null;
};

interface MessageAnAgentV1NodeBase {
  type: 'n8n-nodes-base.messageAnAgent';
  version: 1;
}

export type MessageAnAgentV1ParamsNode = MessageAnAgentV1NodeBase & {
  config: NodeConfig<MessageAnAgentV1Params>;
  output?: Items<MessageAnAgentV1Output>;
};

export type MessageAnAgentV1Node = MessageAnAgentV1ParamsNode;